import {migrateDocument} from './migrations.js';
import {validateImport} from './model.mjs';
export function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('catastrophe-atelie-v1',2);r.onupgradeneeded=()=>{for(const name of ['fichas','versions','library'])if(!r.result.objectStoreNames.contains(name))r.result.createObjectStore(name,{keyPath:'id'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
export function request(db,mode,action,store='fichas'){return new Promise((resolve,reject)=>{const t=db.transaction(store,mode);let value;const r=action(t.objectStore(store));r.onsuccess=()=>value=r.result;t.oncomplete=()=>resolve(value);t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||Error('Operação de armazenamento interrompida.'));});}
export async function saveDocument(db,document,all,storage=localStorage){const d=validateImport(document);if(db)await request(db,'readwrite',s=>s.put(d));else storage.setItem('catastrophe-fallback',JSON.stringify(all));try{storage.setItem('catastrophe-recovery-'+d.id,JSON.stringify(d));}catch{/* IndexedDB remains the authoritative copy. */}return d;}
export async function saveVersion(db,doc,title='Cópia automática',automatic=false){if(!db)throw Error('As versões precisam do armazenamento IndexedDB. Exporte JSON como backup.');const versions=await request(db,'readonly',s=>s.getAll(),'versions');const owned=versions.filter(v=>v.docId===doc.id).sort((a,b)=>b.date-a.date);if(automatic&&owned.some(v=>v.automatic&&Date.now()-v.date<120000))return;if(!automatic&&owned.filter(v=>!v.automatic).length>=40)throw Error('Limite de 40 versões nomeadas. Exporte JSON para guardar outra cópia.');const item={id:crypto.randomUUID(),docId:doc.id,title,date:Date.now(),automatic,document:structuredClone(doc)};await request(db,'readwrite',s=>s.put(item),'versions');for(const v of (automatic?owned.filter(v=>v.automatic).slice(19):[]))await request(db,'readwrite',s=>s.delete(v.id),'versions');return item;}
export async function loadDocuments(db,storage=localStorage){let raw=db?await request(db,'readonly',s=>s.getAll()):JSON.parse(storage.getItem('catastrophe-fallback')||'[]');const result=[],errors=[];const recoveries=[];for(let i=0;i<storage.length;i++){const key=storage.key(i);if(key?.startsWith('catastrophe-recovery-'))try{recoveries.push(JSON.parse(storage.getItem(key)));}catch{errors.push(key);}}for(const item of [...raw,...recoveries])try{const valid=validateImport(migrateDocument(item)),index=result.findIndex(x=>x.id===valid.id);if(index<0)result.push(valid);else if(valid.updated>result[index].updated)result[index]=valid;}catch{errors.push(item?.id||'Arquivo desconhecido');}return {documents:result,errors};}
